// Question: does a dated document list and spacious, unassisted editor provide a useful minimal base?
const seed=()=>({"name": "Jordan Davis", "focuses": [{"id": 1, "title": "Position focus · 2026", "start": "2026-01-01", "end": "2026-12-31", "sections": []}, {"id": 2, "title": "Position focus · 2025", "start": "2025-01-01", "end": "2025-12-31", "sections": [{"kind": "Core objective", "objective": "Build and release a clearer next-step screen for one video devotional, using AI to help write code.", "goals": ["Test the next-step screen with 20 viewers and record how many find the next step.", "Improve the screen based on feedback, then repeat the test with 20 viewers."]}, {"kind": "Core objective", "objective": "Improve the clarity of the devotional viewing experience.", "goals": ["Identify two points where viewers struggle to understand what to do next.", "Test revised instructions with five viewers and record their feedback."]}, {"kind": "Personal development", "objective": "Create an internal hub system for hosting prototypes.", "goals": ["Collect and gather all hostable URLs from four different departments.", "Create a prototype hub and lay out the URLs for each of the four departments.", "Collect feedback on each department’s reception of the hosting platform."]}, {"kind": "Leadership initiative", "objective": "Facilitate 50% of the show-and-tell meetings for the current quarter.", "goals": ["Gather openers or fun topics for each of the available slots for ShareChat.", "Bookmark the show-and-tell facilitation guides in the browser. Review good-practice notes before each session.", "Encourage one team member who has not facilitated before to lead a session. Provide tips and a starter activity, and offer a practice session together."]}]}]});
let s=seed(),page='list',selected=1,topic='Objectives',saved='';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const focus=()=>s.focuses.find(f=>f.id===selected);
const button=(label,action,cls='')=>`<button type="button" class="${cls}" data-action="${action}">${label}</button>`;
const date=x=>x?new Date(x+'T12:00:00').toLocaleDateString('en-NZ',{day:'numeric',month:'short',year:'numeric'}):'No date';
function state(){document.querySelector('#state').textContent=JSON.stringify(s,null,2)}
function go(p){page=p;saved='';render();window.scrollTo(0,0)}
function render(){document.querySelector('#app').innerHTML=`<aside><div class="brand"><span>♙</span> Lantern</div><nav>${[['list','◎','Position focuses'],['guide','▤','Guide'],['account','⚙','Account']].map(([p,i,t])=>button(i+'　'+t,'nav:'+p,(page===p||p==='list'&&page==='editor')?'active':'')).join('')}</nav><div class="aside-foot">Navy / focused base<br>Fourth prototype · menu under review</div></aside><main class="main"><div class="demo"><span>PROTOTYPE · Temporary memory · Refresh clears changes</span>${button('Reset demo','reset')}</div><div class="workspace">${page==='list'?list():page==='editor'?editor():page==='guide'?guide():account()}<details class="state"><summary>Prototype state</summary><pre id="state"></pre></details></div></main>`;state()}
function list(){return `<header><div><h1>Position focuses</h1><p class="muted">Your documents, organised by period.</p></div>${button('New position focus','new','primary')}</header><table class="focus-list"><thead><tr><th>Document</th><th>Period</th><th></th></tr></thead><tbody>${[...s.focuses].sort((a,b)=>b.start.localeCompare(a.start)).map(f=>`<tr><td>${button(esc(f.title),'open:'+f.id,'link')}</td><td class="period">${date(f.start)} – ${date(f.end)}</td><td>${button('Open','open:'+f.id)}</td></tr>`).join('')}</tbody></table><p class="muted" style="margin-top:24px">The current document starts empty. The 2025 document contains an illustrative example.</p>`}
function editor(){const f=focus();return `${button('← Position focuses','nav:list','link back')}<header><div><h1>${esc(f.title)}</h1><p class="muted">${date(f.start)} – ${date(f.end)}</p></div>${button('Edit title & dates','metadata')}</header>${f.sections.length?f.sections.map((x,i)=>`<section class="read-section"><div class="read-objective"><div class="row"><h2>Objective ${i+1}</h2>${button('Edit','editobjective:'+i,'link')}</div>${x.kind!=='Core objective'?`<span class="badge">${esc(x.kind)}</span>`:''}<p class="read-text">${esc(x.objective)||'<span class="muted">No objective yet.</span>'}</p>${button('Remove objective','remove:'+i,'link danger small-action')}</div><div class="read-goals"><h3>SMART goals</h3>${x.goals.map((g,j)=>`<div class="read-goal"><span class="goal-number">${j+1}</span><p class="read-text">${esc(g)}</p><div>${button('Edit',`editgoal:${i}:${j}`,'link')}${button('Remove',`removegoal:${i}:${j}`,'link danger small-action')}</div></div>`).join('')||'<p class="muted">No goals yet.</p>'}${button('+ Add SMART goal','goal:'+i,'link')}</div></section>`).join(''):`<div class="empty-base"><h2>A blank position focus</h2><p class="muted">Add your first objective when you’re ready.</p>${button('Add objective','add:Core objective','primary')}</div>`}<div class="editor-actions"><div>${button('+ Add objective','add:Core objective')} ${button('+ Add optional focus','optional')}</div><span class="save-status">${esc(saved)}</span></div>`}
let editing=null;
function editText(kind,i,j,concern){editing={kind,i,j,concern};const value=kind==='objective'?focus().sections[i].objective:kind==='goal'?focus().sections[i].goals[j]:'';const label=kind==='goal'||kind==='newgoal'?'SMART goal':'Objective';modal(`<form id="edit-form"><h2>${kind.startsWith('new')?'Add':'Edit'} ${label.toLowerCase()}</h2>${concern&&concern!=='Core objective'?`<p class="badge">${esc(concern)}</p>`:''}<label for="edit-text">${label}</label><textarea id="edit-text" required autofocus>${esc(value)}</textarea><div class="dialog-actions">${button('Cancel','close')}<button type="submit" class="primary">Save changes</button></div></form>`)}
function editMetadata(){editing={kind:'metadata'};const f=focus();modal(`<form id="edit-form"><h2>Edit title & dates</h2><label for="edit-title">Document title</label><input id="edit-title" required value="${esc(f.title)}"><div class="metadata"><div><label for="edit-start">Period starts</label><input id="edit-start" type="date" value="${f.start}"></div><div><label for="edit-end">Period ends</label><input id="edit-end" type="date" value="${f.end}"></div></div><div class="dialog-actions">${button('Cancel','close')}<button type="submit" class="primary">Save changes</button></div></form>`)}
document.addEventListener('submit',e=>{if(e.target.id!=='edit-form')return;e.preventDefault();const f=focus(),x=editing;if(x.kind==='metadata'){f.title=document.querySelector('#edit-title').value;f.start=document.querySelector('#edit-start').value;f.end=document.querySelector('#edit-end').value}else{const value=document.querySelector('#edit-text').value.trim();if(!value)return; if(x.kind==='objective')f.sections[x.i].objective=value;if(x.kind==='goal')f.sections[x.i].goals[x.j]=value;if(x.kind==='newobjective')f.sections.push({kind:x.concern,objective:value,goals:[]});if(x.kind==='newgoal')f.sections[x.i].goals.push(value)}document.querySelector('#modal').close();saved='Saved in this session';render();toast(saved)});
function guide(){return `<header><div><h1>Guide</h1><p class="muted">A short reference to read separately from your document.</p></div></header><div class="tabs">${['Objectives','SMART goals','Example'].map(t=>button(t,'topic:'+t,topic===t?'active':'')).join('')}</div><div class="card guide-copy">${topic==='Objectives'?`<h2>Describe the outcome you want to achieve</h2><p>An objective gives your work a clear purpose. Say who it serves and what you want to change.</p><div class="visual"><div><b>People</b>Who you serve</div><span>→</span><div><b>Outcome</b>What changes</div><span>→</span><div><b>Contribution</b>Why it matters</div></div>`:topic==='SMART goals'?`<h2>Make the objective actionable</h2><p>Write a specific action, a measurable result, and a time frame. Check that it is achievable and relevant to the objective.</p><div class="visual"><div><b>Action</b>What you will do</div><span>+</span><div><b>Measure</b>What success means</div><span>+</span><div><b>Time</b>By when</div></div>`:`<h2>Example objective</h2><p>Build and release a clearer next-step screen for one video devotional, using AI to help write code.</p><h2>SMART goal</h2><p>By Month 6, test with 20 viewers; at least 16 can find the next step.</p><small>Illustrative target and timing.</small>`}</div>`}
function account(){return `<header><h1>Account</h1></header><div class="card"><label for="name">Display name</label><input id="name" value="${esc(s.name)}" data-name><p class="muted" style="margin:24px 0">jordan@example.test · Demo account</p>${button('Save name','savename','primary')}</div>`}
function modal(html){document.querySelector('#modal').innerHTML=html;if(!document.querySelector('#modal').open)document.querySelector('#modal').showModal()}
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(window.timer);window.timer=setTimeout(()=>el.style.display='none',2500)}
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.field)focus()[el.dataset.field]=el.value;if(el.hasAttribute('data-objective'))focus().sections[+el.dataset.section].objective=el.value;if(el.hasAttribute('data-goal'))focus().sections[+el.dataset.section].goals[+el.dataset.goal]=el.value;if(el.hasAttribute('data-name'))s.name=el.value;saved='Unsaved changes';const status=document.querySelector('#save-status');if(status)status.textContent=saved;state()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const [a,v,j]=b.dataset.action.split(':');if(a==='nav')go(v);if(a==='open'){selected=+v;go('editor')}if(a==='new'){const id=Date.now();s.focuses.unshift({id,title:'Untitled position focus',start:'',end:'',sections:[]});selected=id;go('editor')}if(a==='add'){document.querySelector('#modal').close();editText('newobjective',null,null,v)}if(a==='goal')editText('newgoal',+v);if(a==='editobjective')editText('objective',+v);if(a==='editgoal')editText('goal',+v,+j);if(a==='metadata')editMetadata();if(a==='remove'||a==='removegoal')modal(`<h2>Remove this ${a==='remove'?'objective and its goals':'goal'}?</h2><p>This changes only your temporary document.</p>${button('Remove',`confirm${a}:${v}${j===undefined?'':':'+j}`,'danger')} ${button('Cancel','close')}`);if(a==='confirmremove'){focus().sections.splice(+v,1);document.querySelector('#modal').close();render()}if(a==='confirmremovegoal'){focus().sections[+v].goals.splice(+j,1);document.querySelector('#modal').close();render()}if(a==='optional')modal(`<h2>Add an optional focus</h2><p>The same objective and SMART goals, with a label for its purpose.</p><div class="stack">${button('Personal development','add:Personal development')}${button('Leadership initiative','add:Leadership initiative')}</div><p style="margin-top:24px">${button('Cancel','close')}</p>`);if(a==='close')document.querySelector('#modal').close();if(a==='save'){saved='Saved in this session';render();toast(saved)}if(a==='savename')toast('Name saved in this session');if(a==='topic'){topic=v;render()}if(a==='reset'){s=seed();selected=1;go('list');toast('Demo reset')}});
render();
